 public Definicion(String t,String n,Campo[] c,String[] columnas) { tabla=t; titulo=n; campos=c; this.columnas=columnas; }
 private static void put(Definicion d) { TODAS.put(d.tabla,d); }
 public static Definicion de(String t) { Definicion d = TODAS.get(t); if(d==null) throw new IllegalArgumentException(t); return d; }
 public Campo campo(String clave) { for(Campo c:campos) if(c.clave.equals(clave)) return c; return null; }
 public String fecha() { if(tabla.equals("tareas"))return "fechaVencimiento"; for(Campo c:campos) if(c.tipo.startsWith("fecha")) return c.clave; return ""; }
 public boolean soloConsulta() { return tabla.equals("registros_investigacion") || tabla.equals("historial_postergaciones"); }
